@if($confirmSubmit)<section class="panel padded confirmation-panel" aria-labelledby="confirm-submit-title"><h2 id="confirm-submit-title">Ready to finish?</h2><p>{{ count($attempt->answers) }} of {{ $attempt->total }} questions are answered. Your answers cannot be changed after submission.</p><div class="button-row"><button class="btn btn-primary" wire:click="submit" wire:loading.attr="disabled">Confirm submission</button><button class="btn btn-secondary" wire:click="$set('confirmSubmit',false)">Keep practising</button></div></section>@endif<div class="exam-layout"><section class="panel question-panel"><div class="flex-between"><p class="eyebrow">QUESTION {{ $current+1 }} OF {{ $attempt->total }}</p><span class="save-status"><span wire:loading wire:target="choose">Saving…</span><span wire:loading.remove wire:target="choose">{{ $attempt->saved_at?'Saved '.$attempt->saved_at->copy()->timezone('Asia/Kathmandu')->format('g:i A'):'Ready to begin' }}</span></span></div><div class="question-progress"><span style="width:{{ ($current+1)/$attempt->total*100 }}%"></span></div><h2>{{ $questions[$current]['prompt'] }}</h2><div class="answer-options" role="group" aria-label="Answer choices">@foreach($questions[$current]['options'] as $i=>$option)<button @class(['answer-option','selected'=>isset($attempt->answers[$current]) && (int)$attempt->answers[$current]===$i]) wire:click="choose({{ $i }})" wire:loading.attr="disabled" wire:key="answer-{{ $current }}-{{ $i }}" aria-pressed="{{ isset($attempt->answers[$current]) && (int)$attempt->answers[$current]===$i?'true':'false' }}"><span>{{ chr(65+$i) }}</span>{{ $option }}</button>@endforeach</div><div class="button-row spread"><button class="btn btn-secondary" wire:click="goTo({{ $current-1 }})" @disabled($current===0)>← Previous</button>@if($current<$attempt->total-1)<button class="btn btn-primary" wire:click="goTo({{ $current+1 }})">Next question →</button>@else<button class="btn btn-primary" wire:click="$set('confirmSubmit',true)">Su